import React from "react";
import { motion } from "framer-motion";

export default function StudentDashboard() {
  const stats = [
    { title: "Total Entries", value: 42 },
    { title: "Private Notes", value: 28 },
    { title: "Shared Notes", value: 14 },
    { title: "Tags Used", value: 10 },
  ];

  const recentEntries = [
    {
      title: "My Exam Prep Plan",
      date: "2025-08-30",
      mood: "😊",
      tags: ["Study", "Motivation"],
    },
    {
      title: "Team Project Meeting",
      date: "2025-08-28",
      mood: "😐",
      tags: ["Work", "Collab"],
    },
  ];

  return (
    <div className="space-y-8">
      {/* Stats */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
        {stats.map((stat, index) => (
          <motion.div
            key={index}
            whileHover={{ scale: 1.05 }}
            className="bg-white shadow-lg rounded-2xl p-6 text-center"
          >
            <p className="text-gray-500">{stat.title}</p>
            <h2 className="text-3xl font-bold text-indigo-600">{stat.value}</h2>
          </motion.div>
        ))}
      </div>

      {/* Recent Entries */}
      <div className="bg-white shadow-md rounded-2xl p-6">
        <h3 className="text-xl font-semibold text-gray-800 mb-4">
          Recent Entries
        </h3>
        <table className="w-full text-left border-collapse">
          <thead>
            <tr className="bg-gray-100">
              <th className="p-3">Title</th>
              <th className="p-3">Date</th>
              <th className="p-3">Mood</th>
              <th className="p-3">Tags</th>
            </tr>
          </thead>
          <tbody>
            {recentEntries.map((entry, i) => (
              <tr
                key={i}
                className="border-b hover:bg-gray-50 transition-colors"
              >
                <td className="p-3">{entry.title}</td>
                <td className="p-3">{entry.date}</td>
                <td className="p-3">{entry.mood}</td>
                <td className="p-3">{entry.tags.join(", ")}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}
